import { describe, it, expect } from 'vitest'
import {
  SPIN_BANNERS,
  getSpinBanner,
  spinCurrency,
  spinBalance,
  spinsUsed,
  spinsLeft,
  clampSpinCount,
  chanceForExclusiveSpin,
  runSpinBatch,
  type SpinBanner,
  type SpinnerPlayer,
} from '../src/engine/gacha'
import { roundGems } from '../src/engine/rng'
import { characterMap } from '../src/data'

// Parity fixtures generated by RUNNING the bot's season-engine.js
// chanceForExclusiveSpin() against the real banner configs.

function makePlayer(overrides: Partial<SpinnerPlayer> = {}): SpinnerPlayer {
  return {
    wallet: { solars: 100, gems: 1000 },
    ownedCharacters: [],
    ...overrides,
  }
}

describe('banner table (bot parity)', () => {
  it('gogeta odds: dead 1–230, flat 0.80 from 231, no hard pity', () => {
    const b = SPIN_BANNERS.gogeta!
    expect(b.deadZoneUntil).toBe(230)
    expect(b.plateauChance).toBe(0.8)
    expect(b.pityAt).toBe(9999)
    expect(b.costPerSpin).toBe(1.5)
    expect(chanceForExclusiveSpin(1, b)).toBe(0)
    expect(chanceForExclusiveSpin(230, b)).toBe(0)
    expect(chanceForExclusiveSpin(231, b)).toBe(0.8)
    expect(chanceForExclusiveSpin(250, b)).toBe(0.8)
  })

  it('remi odds: 234 dead, 0.12 plateau, guaranteed at 300', () => {
    const b = SPIN_BANNERS.remi!
    expect(chanceForExclusiveSpin(299, b)).toBe(0.12)
    expect(chanceForExclusiveSpin(300, b)).toBe(1)
  })

  it('victoria: first spin past dead zone is guaranteed', () => {
    const b = SPIN_BANNERS.victoria_minayoko!
    expect(chanceForExclusiveSpin(276, b)).toBe(0)
    expect(chanceForExclusiveSpin(277, b)).toBe(1)
  })

  it('ships14 banners, every one with a character in characters.json', () => {
    expect(Object.keys(SPIN_BANNERS)).toHaveLength(14)
    for (const id of Object.keys(SPIN_BANNERS)) {
      expect(characterMap[id], `character ${id} missing`).toBeTruthy()
    }
  })

  it('getSpinBanner is case-insensitive and total', () => {
    expect(getSpinBanner('Gogeta')?.id).toBe('gogeta')
    expect(getSpinBanner('nope')).toBeNull()
    expect(getSpinBanner(null)).toBeNull()
  })

  it('spinCurrency defaults to gems, solars banners say so', () => {
    expect(spinCurrency(SPIN_BANNERS.gogeta!)).toBe('gems')
    expect(spinCurrency(SPIN_BANNERS.rengoku!)).toBe('solars')
  })
})

describe('spin helpers', () => {
  it('spinBalance normalises solars (floor) and gems (2dp)', () => {
    expect(spinBalance({ wallet: { solars: 12.7 } }, SPIN_BANNERS.rengoku!)).toBe(12)
    expect(spinBalance({ wallet: { gems: 4.555 } }, SPIN_BANNERS.gogeta!)).toBe(4.56)
  })

  it('spinsUsed/spinsLeft read the per-banner counter field', () => {
    const p = makePlayer({ gogetaSpins: 10 } as Partial<SpinnerPlayer>)
    const b = SPIN_BANNERS.gogeta!
    expect(spinsUsed(p, b)).toBe(10)
    expect(spinsLeft(p, b)).toBe(240)
  })

  it('clampSpinCount respects per-command and lifetime caps', () => {
    const b = SPIN_BANNERS.gogeta! // command 20, lifetime 250
    expect(clampSpinCount(b, 100)).toBe(20)
    expect(clampSpinCount(b, 3)).toBe(3)
    expect(clampSpinCount(b, 0)).toBe(1) // floors to at least 1
    expect(clampSpinCount(b, -5)).toBe(1)
  })

  it('roundGems matches the bot', () => {
    expect(roundGems(1.5)).toBe(1.5)
    expect(roundGems(4.555)).toBe(4.56)
    expect(roundGems(NaN)).toBe(0)
  })
})

describe('runSpinBatch', () => {
  // A small synthetic banner so tests exercise every branch quickly.
  const banner: SpinBanner = {
    id: 'test_char',
    spinField: 'testCharSpins',
    costPerSpin: 1,
    currency: 'gems',
    deadZoneUntil: 2,
    plateauChance: 0.5,
    pityAt: 5,
    maxSpinsPerPlayer: 10,
    maxSpinsPerCommand: 5,
    exclusive: true,
  }

  it('returns owned without spending when already owned', () => {
    const p = makePlayer({ ownedCharacters: ['test_char'] })
    const r = runSpinBatch(p, banner, 5, () => 0)
    expect(r.reason).toBe('owned')
    expect(p.wallet.gems).toBe(1000)
  })

  it('cannot afford: reason gems with balance and cost', () => {
    const p = makePlayer({ wallet: { solars: 0, gems: 0.5 } })
    const r = runSpinBatch(p, banner, 5, () => 0)
    expect(r.reason).toBe('gems')
    expect(r.gems).toBe(0.5)
    expect(r.cost).toBe(1)
    expect(r.currency).toBe('gems')
    expect(r.spinsUsed ?? 0).toBe(0)
  })

  it('dead zone never wins; plateau wins on a passing roll; batch stops at the win', () => {
    const p = makePlayer()
    // rng 0.9: fails dead zone (chance 0), fails 0.5 plateau until pity spin 5
    const r = runSpinBatch(p, banner, 5, () => 0.9)
    expect(r.reason).toBe('won')
    expect(r.results?.map((x) => x.won)).toEqual([false, false, false, false, true])
    expect(r.spinsUsed).toBe(5)
    expect(p.ownedCharacters).toContain('test_char')
    expect(p.wallet.gems).toBe(995) // 5 × 1 gem
    expect(spinsUsed(p, banner)).toBe(5)
  })

  it('dead zone loses even on a passing rng (chance is 0)', () => {
    const p = makePlayer()
    const r = runSpinBatch(p, banner, 2, () => 0) // rng 0 always
    expect(r.reason).toBe('exhausted')
    expect(r.results?.every((x) => !x.won)).toBe(true)
    expect(spinsUsed(p, banner)).toBe(2)
    expect(p.ownedCharacters).toHaveLength(0)
  })

  it('wins on the first live spin when the plateau roll passes', () => {
    const p = makePlayer()
    const r = runSpinBatch(p, banner, 5, () => 0) // 0 < 0.5 → win at spin 3
    expect(r.reason).toBe('won')
    expect(r.results?.map((x) => x.spin)).toEqual([1, 2, 3])
    expect(r.results?.[2]?.won).toBe(true)
  })

  it('stops when funds run out mid-batch', () => {
    const p = makePlayer({ wallet: { solars: 0, gems: 2.5 } })
    const r = runSpinBatch(p, banner, 5, () => 0.9) // never wins
    expect(r.reason).toBe('exhausted')
    expect(r.spinsUsed).toBe(2) // 2.5 → 1.5 → 0.5, third spin unaffordable
    expect(p.wallet.gems).toBe(0.5)
  })

  it('enforces the lifetime cap: exhausted_lifetime when no spins left', () => {
    const p = makePlayer({ testCharSpins: 10 } as Partial<SpinnerPlayer>)
    const r = runSpinBatch(p, banner, 5, () => 0)
    expect(r.reason).toBe('exhausted_lifetime')
    expect(r.spinsUsed ?? 0).toBe(0)
  })

  it('batch stops exactly at the lifetime cap', () => {
    // pityAt past the cap (like gogeta/remi's 9999) so spins never auto-win
    const capBanner: SpinBanner = { ...banner, pityAt: 9999 }
    const p = makePlayer({ testCharSpins: 8 } as Partial<SpinnerPlayer>)
    const r = runSpinBatch(p, capBanner, 5, () => 0.9) // never wins
    expect(r.spinsUsed).toBe(2) // spins 9, 10 then the cap stops the loop
    expect(spinsUsed(p, capBanner)).toBe(10)
  })

  it('solars banner spends solars and keeps them whole', () => {
    const p = makePlayer({ wallet: { solars: 160_000, gems: 0 } })
    const r = runSpinBatch(p, SPIN_BANNERS.rengoku!, 3, () => 0.9)
    expect(r.currency).toBe('solars')
    expect(r.spinsUsed).toBe(3)
    expect(p.wallet.solars).toBe(160_000 - 3 * 50_000) // 10 000 left
  })

  it('gem banner rounds the wallet through roundGems each spin', () => {
    const p = makePlayer({ wallet: { solars: 0, gems: 4 } })
    // gogeta: cost 1.5, dead zone through 230 — rng 1 never wins
    const r = runSpinBatch(p, SPIN_BANNERS.gogeta!, 20, () => 1)
    expect(r.spinsUsed).toBe(2) // 4 → 2.5 → 1.0, third unaffordable
    expect(p.wallet.gems).toBe(1)
  })

  it('is deterministic under a seeded rng', () => {
    const run = () => {
      const p = makePlayer({ wallet: { solars: 0, gems: 100 } })
      let i = 0
      const seq = [0.9, 0.9, 0.9, 0.9, 0.1] // lose ×4 then win at pity
      runSpinBatch(p, banner, 5, () => seq[i++ % seq.length]!)
      return p
    }
    expect(run()).toEqual(run())
  })
})
